e, null as currency, null is_refund, null as city, \"Customer State\" as state, case when lower(am.\"Reason for Credit Entry\") like \'%cancel%\' then \'cancelled\' when lower(am.\"Reason for Credit Entry\") like \'%return%\' then \'returned\' else lower(am.\"Reason for Credit Entry\") end order_status, COALESCE( TRY_TO_DATE(\"Order Date\", \'MM/DD/YYYY\'), TRY_TO_DATE(\"Order Date\", \'DD-MM-YY\') ) AS order_date, order_date as order_timestamp, null as shipping_price, null as NUMBER_OF_PRODUCTS_IN_COMBO, QUANTITY::int as suborder_quantity, null as SHIPPED_QUANTITY, null as RETURNED_QUANTITY, null as CANCELLED_QUANTITY, null as RETURN_SALES, null as CANCEL_SALES, (\"Supplier Listed Price (Incl. GST + Commission)\"::int / 1.13) as tax, null as SUBORDER_MRP, s.CATEGORY as category, UPPER(coalesce(product_name,\"Product Name\")) as Product_Name_Mapped, null as Report_Category, null as Product_Pack, null as Product_quantity, null as DISCOUNT, \"Supplier Listed Price (Incl. GST + Commission)\"::int as selling_price, null as MRP_SALES, null as DISCOUNT_MRP, null as NEW_CUSTOMER_FLAG, null as NEW_CUSTOMER_FLAG_MONTH, null WAREHOUSE_NAME, null as return_flag, null as DAYS_IN_SHIPMENT, \'MEESHO\' as CHANNEL, NULL as Shopify_UTM_source, NULL as Shopify_UTM_Medium, NULL AS UTM_CAMPAIGN, eef.payment_mode, null as IMPORT_DATE, null as LAST_UPDATE_DATE, null as INVOICE_DATE, null as company_name, null as pin_code, NULL as FINAL_UTM_CAMPAIGN, \'Synced\' as EasyEcom_Sync_Flag, null as cancelled_at, \'MEESHO\' as Data_Source ,s.MARKETPLACE_SKU as exception_sku FROM RPSG_DB.MAPLEMONK.sales_report_meesho_order_report AM LEFT JOIN ( select * from rpsg_DB.maplemonk.fact_items_easyecom_drv qualify row_number() over(partition by lower(reference_code),lower(sku) order by 1) = 1 )EEF ON lower(split(AM.\"Sub Order No\",\'_\')[0]::string ) = lower(EEF.reference_code) AND LOWER(AM.SKU) = LOWER(EEF.SKU) left join (select * from (select SKU, BRAND, CATEGORY, MARKETPLACE, \"Marketplace _SKU\" AS 