 coalesce(eef.SELLING_PRICE,try_cast(\"Price before discount\" as float)) as selling_price, null AS MRP_SALES, try_cast(\"Total Discount\" as int) AS DISCOUNT_MRP, NULL AS NEW_CUSTOMER_FLAG, NULL AS NEW_CUSTOMER_FLAG_MONTH, null AS WAREHOUSE_NAME, NULL AS RETURN_FLAG, NULL AS DAYS_IN_SHIPMENT, NULL AS CHANNEL, NULL AS Shopify_UTM_source, NULL AS Shopify_UTM_Medium, NULL AS UTM_CAMPAIGN, coalesce(\"Order Type\",EEF.payment_mode) AS PAYMENT_MODE, NULL AS IMPORT_DATE, NULL AS LAST_UPDATE_DATE, null AS invoice_date, NULL AS company_name, \"Customer\'s Delivery Pincode\" AS pin_code, NULL AS FINAL_UTM_CAMPAIGN, \'Synced\' AS EasyEcom_Sync_Flag, CASE WHEN cancel_sales IS NOT NULL THEN LAST_UPDATE_DATE END AS cancelled_at, \'Meesho\' AS Data_Source ,s.sku as exception_sku FROM rpsg_db.maplemonk.ecom_flipkart_seller_report b LEFT JOIN ( select * from rpsg_DB.maplemonk.fact_items_easyecom_drv qualify row_number() over(partition by lower(reference_code),lower(sku) order by 1) = 1 )eef ON b.\"Order ID\" = EEF.reference_code AND (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = LOWER(EEF.SKU) INNER JOIN ( select * from (select SKU, BRAND, CATEGORY, MARKETPLACE, \"Marketplace _SKU\" AS MARKETPLACE_SKU, \"Product Name Detailed\" AS PRODUCT_NAME, row_number() over (partition by lower(sku) order by 1) rw from rpsg_db.maplemonk.amazon_asin_amazon_asin where sku is not null ) where rw=1 ) S ON (LOWER(REGEXP_REPLACE(SUBSTRING(B.SKU, 8, 18), \'[^a-zA-Z0-9_-]\', \'\'))) = (LOWER(S.sku)); ;",
